diff.code:
// shared narrowing helper
export function assertDefined<T>(v: T, name?: string) {
  if (!v) {
    console.error((name ?? 'value') + ' is missing');
  }
}

// usage
function start(env: Record<string, string | undefined>) {
  const url = env.DATABASE_URL; // string | undefined
  assertDefined(url, 'DATABASE_URL');
  return url.slice(0, 8); // expected: url narrowed to string
}

